import type { RedFlagKind } from './red-flags';

/** Which fixed escalation message a stored chat message is. */
export type EscalationKind = RedFlagKind;

/**
 * Fixed copy shown instead of a model reply when the red-flag detector fires.
 * Never generated by the model, so it cannot drift or be talked out of.
 * No invented helpline numbers: UAE 999 police / 998 ambulance, 112 across much
 * of Europe, 911 in the US; otherwise "a local crisis line".
 */
export const ESCALATION_COPY: Record<EscalationKind, string> = {
  // needs clinician review
  CRISIS:
    "Thank you for telling me. It sounds really hard right now. I'm an automated wellness coach and I can't help keep you safe in a crisis, but people can. If you might act on these thoughts, or you're in danger, call your local emergency number now (UAE: 999 police, 998 ambulance; 112 across much of Europe; 911 in the US). If you're not in immediate danger, please contact a local crisis line or someone you trust today.",
  // needs clinician review
  EMERGENCY:
    "What you're describing could be a medical emergency. Please stop using this app and call your emergency number now (UAE ambulance 998, 112, or 911). If you have chest pain, sudden weakness on one side, slurred speech, or trouble breathing, don't drive yourself.",
};

/**
 * Recognises a stored assistant message as one of the fixed escalation
 * messages (exact match), so the UI can render history as a card too.
 */
export function isEscalationMessage(content: string): EscalationKind | null {
  if (content === ESCALATION_COPY.CRISIS) return 'CRISIS';
  if (content === ESCALATION_COPY.EMERGENCY) return 'EMERGENCY';
  return null;
}
